#[test]
fn unicode_general_category_results_snapshot() {
    let mut rows = String::new();
    for name in [
        "C", "Cc", "Cf", "Cn", "Co", "Cs", "L", "LC", "Ll", "Lm", "Lo", "Lt", "Lu", "M", "Mc",
        "Me", "Mn", "N", "Nd", "Nl", "No", "P", "Pc", "Pd", "Pe", "Pf", "Pi", "Po", "Ps", "S",
        "Sc", "Sk", "Sm", "So", "Z", "Zl", "Zp", "Zs",
    ] {
        for body in [
            format!(r"\p{{{name}}}"),
            format!(r"\P{{gc={name}}}"),
            format!(r"(?<x>[\p{{General_Category={name}}}K])"),
        ] {
            let pattern = JsString::from(body.as_str());
            for flags in ["dug", "diug", "divg", "divy"] {
                for input in ["KaμΣς😀\u{378}\n", "X\r\nA\u{2028}😀", ""] {
                    let input = JsString::from(input);
                    for start in [0, 1, 3] {
                        let script = format!(
                            "let r=new RegExp({pattern:?},{flags:?});r.lastIndex={start};let m=r.exec({input:?});JSON.stringify({{m,index:m?.index,groups:m?.groups,indices:m?.indices,indexGroups:m?.indices?.groups,lastIndex:r.lastIndex,source:r.source}})"
                        );
                        let Value::String(result) = Realm::default().eval(&script).unwrap() else {
                            panic!("{script}")
                        };
                        writeln!(
                            rows,
                            "{body:?} flags={flags:?} input={input:?} lastIndex={start} {result:?}"
                        )
                        .unwrap();
                    }
                }
            }
        }
    }
    insta::assert_snapshot!(rows);
}

#[test]
fn unicode_general_category_captures_context_and_pair_starts() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/^(?<x>([\p{{gc=Lu}}K]))$/dim{mode}g,m=r.exec('\u0378\r\nK\u2028');m.index===3&&m[1]==='K'&&m[2]==='K'&&m.indices.groups.x===m.indices[1]&&m.indices[2][1]===4&&r.lastIndex===4"
        ));
        check(&format!(
            r"let r=/(?<__proto__>\p{{gc=So}})/d{mode}y;r.lastIndex=1;let m=r.exec('😀A');m.index===0&&m[1]==='😀'&&m.indices[1][1]===2&&r.lastIndex===2&&Object.getPrototypeOf(m.groups)===null&&m.indices.groups.__proto__===m.indices[1]"
        ));
        check(&format!(
            r"let r=/\p{{Cs}}/d{mode}g;r.lastIndex=1;let m=r.exec('😀\uD800');m.index===2&&m[0]==='\uD800'&&r.lastIndex===3"
        ));
        check(&format!(
            r"let r=/\p{{Cs}}/{mode}y;r.lastIndex=1;r.exec('😀\uD800')===null&&r.lastIndex===0"
        ));
    }
}

#[test]
fn unicode_general_category_consumers_preserve_original_text() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let a=[...'A😀\u0378B'.matchAll(/(?<x>\P{{L}})/d{mode}g)];a.length===2&&a[0][1]==='😀'&&a[0].index===1&&a[0].indices[1][1]===3&&a[1][1]==='\u0378'&&a[1].index===3"
        ));
        check(&format!(
            r"'AB\u0378'.replace(/(?<x>\p{{Letter}})/{mode}g,'<$1:$<x>>')==='<A:A><B:B>\u0378'"
        ));
        check(&format!(
            r"'\u0378AB\u0378'.split(/(\p{{General_Category=Letter}})/{mode}).join('|')==='\u0378|A||B|\u0378'&&'\u0378😀A'.search(/\p{{L}}/{mode})===3&&'AB\u0378'.match(/\p{{L}}/{mode}g).join('')==='AB'"
        ));
        check(&format!(
            r"let t='',x='AB\u0378A'.replace(/(\p{{L}})/{mode}g,(m,c,p)=>{{t+=p;return '_'}});x==='__\u0378_'&&t==='013'"
        ));
    }
}

#[test]
fn unicode_general_category_clones_coercions_and_strict_writes() {
    check(
        r"let r=/^(?<x>\p{gc=Lu})$/dmu,c=new RegExp(r,'divy');c.source==='^(?<x>\\p{gc=Lu})$'&&c.unicodeSets&&!c.unicode&&!c.multiline&&c.exec('a').groups.x==='a'&&c.lastIndex===1",
    );
    check(
        r"let t='',r=/\p{So}/uy;r.lastIndex={valueOf(){t+='i';return 1}};let m=r.exec({toString(){t+='s';return '😀'}});t==='si'&&m[0]==='😀'&&m.index===0&&r.lastIndex===2",
    );
    check(
        r"let r=/\p{Lu}/vy;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('A')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===0",
    );
    check(
        r"let r=/\p{Cs}/vy;r.lastIndex=1;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('😀\uD800')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===1",
    );
}

#[test]
fn unicode_general_category_repeated_sources_captures_and_collection() {
    assert_eq!(Limits::default().max_steps, None);
    assert_eq!(Limits::default().max_heap_entries, None);
    let mut realm = Realm::default();
    realm.eval("let p='^'+'('.repeat(3000)+'['+'\\\\p{Lu}\\\\p{Cs}\\\\p{ASCII}'.repeat(10000)+']'+')'.repeat(3000)+'$',r=new RegExp(p,'dmvg'),c=new RegExp(r),text='\\u0378'.repeat(100000)+'\\nA'").unwrap();
    realm.collect(usize::MAX).unwrap();
    assert_eq!(realm.eval("let m=c.exec(text);m.length===3001&&m[1]==='A'&&m[3000]==='A'&&m.indices[3000][0]===100001&&m.indices[3000][1]===100002&&c.lastIndex===100002"),Ok(Value::Boolean(true)));
    realm.eval("p=null;r=null;c=null;text=null;m=null").unwrap();
    realm.collect(usize::MAX).unwrap();
}

#[test]
fn unicode_general_category_opted_work_and_remaining_sets() {
    let mut realm = Realm::new(Limits {
        max_steps: Some(30000),
        ..Limits::default()
    });
    realm
        .eval("let r=/\\p{Lu}/ug,marker=0,text='\\u0378'.repeat(10000);r.lastIndex=1")
        .unwrap();
    assert!(matches!(
        realm.eval("try{r.exec(text)}catch{marker=1}finally{marker=2}"),
        Err(Error::Limit { .. })
    ));
    assert_eq!(
        realm.eval("marker===0&&r.lastIndex===1"),
        Ok(Value::Boolean(true))
    );
    check(
        r#"let m=/\p{Script_Extensions=Latin}/u.exec('A');JSON.stringify(m)==='["A"]'&&m.index===0&&m.input==='A'"#,
    );
    check(
        r"let m=/[\p{Lu}&&A]/v.exec('A');m!==null&&m.length===1&&m[0]==='A'&&m.index===0&&m.input==='A'",
    );
    check(r"/[\p{Lu}--A]/v.exec('A')===null");
    check(
        r"let s=String.fromCodePoint(0x4b),m=/[\p{Lu}--A]/v.exec(s);m!==null&&m.length===1&&m[0]===s&&m.index===0&&m.input===s",
    );
    for source in [r"/\p{Lu}+b/u.exec('AA')", r"/\p{Lu}A/v.exec('AA')"] {
        assert!(
            matches!(
                Realm::default().eval(source),
                Err(Error::Unsupported { .. })
            ),
            "{source}"
        );
    }
}

#[test]
fn unicode_general_category_repetitions_retain_last_capture_and_outside_words() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/\B(?<x>\p{{So}})+\B/d{mode}g,m=r.exec('\u0378😀😀😀\u0378');m.index===1&&m[0]==='😀😀😀'&&m.groups.x==='😀'&&m.indices.groups.x[0]===5&&m.indices.groups.x[1]===7&&r.lastIndex===7"
        ));
    }
}

#[test]
fn unicode_general_category_former_direct_eval_context_executes_normally() {
    check(
        r#"let marker=0,result;try{result=eval("marker=1; /\\p{General_Category=Letter}/u.test('a');")}catch{marker=2}finally{marker=3}marker===3&&result===true"#,
    );
}
